fields.InputDefinition:
{
  "goal": "IMPORTANT: To open the 'People' entity, use the LEFT sidebar 'Search record types...' box — type 'People' and click the node named EXACTLY 'People' (individual people, ~3,000 records; NOT 'Person Job Functions', 'Member Profiles', 'Memberships' or 'Membership Types'); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=MJ_BizApps_Common:%20People. Do NOT fight a group expand-chevron. Open the 'People' entity grid (~3,000 records across many pages). Use the grid's pagination control at the bottom to advance to the next page (page 2); verify a different page of people rows is shown. Do not repeatedly toggle the same control. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
